--
-- Triggers `medicalrecords`
--
DELIMITER $$
CREATE TRIGGER `after_medical_record_insert` AFTER INSERT ON `medicalrecords` FOR EACH ROW BEGIN
    DECLARE record_count INT;

    -- Count how many records this patient now has
    SELECT COUNT(*) INTO record_count 
    FROM medicalrecords 
    WHERE patient_id = NEW.patient_id;

    -- If they have 3 or more, and are NOT already in the fidelity table
    IF record_count >= 3 THEN
        VALUES (NEW.patient_id, record_count, NOW(), NOW())
        ON DUPLICATE KEY UPDATE 
            medical_records_count = record_count,
            updated_at = NOW();
    END IF;
END
$$
DELIMITER ;

