INSERT INTO `conduite_a_tenir` (`id`, `title`, `clinique`, `biologie`, `radio`, `traitement`, `details`, `created_at`, `uuid`, `updated_at`, `is_deleted`, `needs_sync`, `source_id`) VALUES
(1, 'viroses en pediatrie', '▪️Âge de l’enfant\r\n▪️Chronologie fièvre ↔️ éruption\r\n▪️Type de lésions : macules, papules, vésicules, purpura…\r\n▪️Topographie et extension\r\n▪️Signes associés : ORL, digestifs, respiratoires, neuro\r\n▪️État général (enfant bien vs toxique)\r\n\r\n↗️Rougeole\r\n▪️Fièvre élevée + toux, coryza, conjonctivite\r\n▪️Taches de Koplik (muqueuse buccale)\r\n▪️Éruption maculo-papuleuse descendante (visage → tronc)\r\n👉 Différence : signes ORL + conjonctivite\r\n\r\n↗️ Rubéole\r\n▪️Fièvre modérée\r\n▪️Adénopathies rétro-auriculaires\r\n▪️Éruption fine, fugace\r\n👉 Enfant peu malade\r\n\r\n↗️Scarlatine\r\n▪️Fièvre + angine\r\n▪️Langue framboisée\r\n▪️Éruption rouge diffuse, granitée\r\n▪️Respect du triangle naso-labial\r\n👉 ATB obligatoire (strepto A)\r\n\r\n↗️Varicelle\r\n▪️Fièvre modérée\r\n▪️Lésions polymorphes (macule → vésicule → croûte)\r\n▪️Prurit important\r\n👉 Lésions d’âges différents = clé diagnostique\r\n\r\n↗️ Roséole infantile (HHV-6)\r\n👶 Nourrisson\r\n▪️Fièvre élevée 3–5 jours\r\n▪️Puis chute brutale de la fièvre → éruption rosée\r\n👉 Éruption APRES la fièvre\r\n\r\n↗️ Syndrome main-pied-bouche\r\n▪️Fièvre modérée\r\n▪️Vésicules buccales + mains + pieds', 'aucune', 'TLT en cas de Signes Respiratoires', 'TRT Symptomatique', '', '2026-01-26 11:07:09', 'bc77501f-427b-11f1-aa44-a0423f4ffaac', '2026-04-27 20:57:34', 0, 0, 'local_server'),
(2, 'Purpura vaculaire', 'Prise des Médicaments récents (ATB, AINS, diurétiques, IEC..)\r\nNotion d’infection récente\r\nDouleurs articulaires, abdominales, hématurie, fièvre\r\nCaractère palpable du purpura\r\nŒdèmes, varices, signes d’insuffisance veineuse\r\nRecherche une atteinte systémique', '▪️NFS + plaquettes\r\n▪️CRP / VS\r\n▪️Urée, créatinine\r\n▪️BU (hématurie, protéinurie)\r\n± Bilan immunologique si suspicion de vascularite systémique', '', '▪️Antihistaminique pour prurit\r\n▪️Émollient', '➡️ Orientation médecin interne', '2026-01-26 17:41:24', 'bc77531a-427b-11f1-aa44-a0423f4ffaac', '2026-04-27 20:57:34', 0, 0, 'local_server'),
(3, 'Proteinurie élevée', '◾️Faut: D\'abord éliminer les faux positifs\r\n▪️Quand tu vois une proteinurie tu ne commences pas par les bilans!\r\n▪️Tu commences par le patient!\r\n▪️Tu fais un examen clinique complet!\r\n▪️Tu prends la TA correctement\r\n▪️Tu regardes s\'il y a des œdèmes au niveau des chevilles, jambes, paupieres\r\n▪️Tu demandes une prise de poids récente\r\n▪️Tu demandes si les urines moussent\r\n▪️Tu evalues la diurese\r\n▪️Tu cherches des signes de rétention hydrosodée\r\n\r\n◾️Ensuite seulement tu interprètes la proteinurie\r\n▪️Une proteinurie avec œdèmes oriente vers une atteinte glomerulaire\r\n▪️Une proteinurie isolée sans signes cliniques est souvent benigne ou fonctionnelle', 'ECBU avec sédiment pour éliminer contamination ou infection.\r\nRecontrôle de la proteinurie\r\nCréatinine DFG, Urée sg \r\nRapport albumine créatinine \r\nGlycémie HbA1c\r\nélectrophorèse des proteines', 'Echographie rénale (chercher signes de chronicité)', '', 'Diagnostic les plus probables a ce stade\r\n▪️Contamination ou infection urinaire (faux positif)\r\n▪️Diabète débutant \r\n▪️HTA méconnue\r\n▪️Début de néphropathie glomérulaire', '2026-01-26 17:50:26', 'bc775428-427b-11f1-aa44-a0423f4ffaac', '2026-04-27 20:57:34', 0, 0, 'local_server'),
(4, 'Alternatifs de #Salbutamol (crise d\'asthme)', '', '', '', '✅#Bricanyl: \r\nEnfant : 0,1_0,2 mg/kg\r\nAdulte : 5_10mg', 'utilisé en nébulisation\r\nAction Rapide mais Courte', '2026-01-26 17:53:16', 'bc775516-427b-11f1-aa44-a0423f4ffaac', '2026-04-27 20:57:34', 0, 0, 'local_server'),
(5, 'Hypophosphoremie', '', 'VIT D\r\nPTH\r\nCALCEMIE\r\nALBUNEMIE', '', '', 'On demande aux patients de manger les fruits secs, chocot, noix, céréales complètes, produits laitiers: lait, yaourt, fromage..\r\nProtéines animales: viande, poulet, poisson, oeufs..\r\nEviter une nutrition hyperglucidique isolée (risque refeeding)', '2026-01-27 14:42:37', 'bc77560f-427b-11f1-aa44-a0423f4ffaac', '2026-04-27 20:57:34', 0, 0, 'local_server'),
(6, 'HTA CHEZ LA FEMME ENCEINTE', 'Rechercher: épigastralgie, trouble visuel, céphalée, ROT, métrorragie', 'FNS\r\nTP/TCK\r\nUREE / CREAT + IONOGRAMME SANGUIN\r\nBILAN HEPATIQUE COMPLET\r\nPROTEINURIE DES 24H\r\n', 'écho obstétricale\r\ndoppler des artères ombilicales, \r\nLes MAF, \r\nvolume du liquide amniotique\r\n', 'ALDOMET 250MG, 1 CP 2XJ ........ 03 MOIS', 'ERCF CHAQUE 48H\r\nDECLENCHEMENT SI 38 SA +/- 3J', '2026-01-27 14:47:21', 'bc775692-427b-11f1-aa44-a0423f4ffaac', '2026-04-27 20:57:34', 0, 0, 'local_server'),
(7, 'ALIMENTS ET ANTICOAGULANTS', 'vit C à forte dose, \r\nl\'oméga 3 (augmente le risque d\'hémorragie) curcuma, \r\ngingembre, \r\nginseng, \r\nle coenzyme Q10 (qui agit de la même manière que la vit K) \r\nvit E', '', '', '', '', '2026-01-27 14:48:49', 'bc775705-427b-11f1-aa44-a0423f4ffaac', '2026-04-27 20:57:34', 0, 0, 'local_server'),
(8, 'Dermatite Atopique en poussée', '', '', '', 'LOCATOP 0.1%, 1 application le soir ........ 03 à 05j\r\nPRODERMA, 1 APP 2 à 4XJ ........ 02 TUBES', '', '2026-01-27 19:11:35', 'bc775778-427b-11f1-aa44-a0423f4ffaac', '2026-04-27 20:57:34', 0, 0, 'local_server'),
(9, 'INTOLERANCE AU LACTOSE', 'POST-PRANDIAL: douleurs abdominales, diarrhées, flatulences \r\nDiarrhées, constipation, Nausées et vomissements\r\nSymptômes extra-digestifs\r\nTroubles mnésiques\r\nCéphalées\r\nDouleurs musculo-squelettiques\r\nTroubles du rythme cardiaque\r\nUlcères buccaux\r\nDyspareunie et troubles menstruels\r\nPollakiurie\r\nEczéma et atopie (sinusite, rhinite allergique, asthme)\r\nAcné', '', '', '', 'test d\'éviction du lactose pdt 02 semaine, réintroduction 250ml de lait 2x/semaine chez Enfant', '2026-01-27 19:18:34', 'bc7757e6-427b-11f1-aa44-a0423f4ffaac', '2026-04-27 20:57:34', 0, 0, 'local_server');
